    const savedTitles = [...new Set(draft.tracks.map(track => track.title).filter(Boolean))].slice(0, ADMIN_IMPORT_LIMITS.files);
    const proposedTitles = [...new Set(proposals.trackTitles.map(track => track.title).filter(title => title && !savedTitles.some(saved => sameName(saved, title))))].slice(0, ADMIN_IMPORT_LIMITS.files);
    const titles = [...savedTitles, ...proposedTitles];
